        }
    });

    test('ignores arch tokens outside the 2-3 digit range so a valid arch still wins', () => {
        expect(extractCudaGpuArch('nvcc -gencode=arch=compute_90,code=sm_90 -DMAX_ARCH=sm_1000 file.cu')).toBe('sm_90');
